Action.Str:
var code = typeof http_response_code === "undefined" ? "" : String(http_response_code);
var response;
try {
  response = JSON.parse(String(http_data));
} catch (_error) {
  response = null;
}
var checkpoint = response && response.checkpoint;
var checkpointDate = Number(checkpoint && checkpoint.date);
var checkpointId = Number(checkpoint && checkpoint.rowId);
if (code !== "200" || !isFinite(checkpointDate) || checkpointDate < 0 || Math.floor(checkpointDate) !== checkpointDate ||
    !isFinite(checkpointId) || checkpointId < 0 || Math.floor(checkpointId) !== checkpointId) {
  var detail = typeof errmsg !== "undefined" && errmsg ? errmsg :
    (typeof http_data !== "undefined" && http_data ? http_data : "No response");
  flashLong("Actual SMS sync could not fetch checkpoint: " + detail);
  exit();
}
setLocal("%syncdate", String(checkpointDate));
setLocal("%syncid", String(checkpointId));

setLocal("%payload", "");
setLocal("%inboxcount", "");
setLocal("%inboxrowcount", "");
setLocal("%drainmore", "");
setLocal("%http_response_code", "");
setLocal("%http_data", "");
setLocal("%errmsg", "");
var rows = typeof inboxrows !== "undefined" && inboxrows ? inboxrows : [];
if (!Array.isArray(rows)) rows = [rows];
if (rows.length === 0) exit();
var events = [];
for (var i = 0; i < rows.length; i++) {
  var parts = String(rows[i]).split("|~sms~|");
  var rowId = parts.length > 0 ? String(parts[0]) : "";
  var dateMs = parts.length > 0 ? String(parts[parts.length - 1]) : "";
  var sender = parts.length >= 2 && parts[1] ? String(parts[1]) : null;
  var body = parts.length >= 4 ? parts.slice(2, parts.length - 1).join("|~sms~|") : null;
  events.push({ rowId: rowId, date: dateMs, sender: sender, message: body });
}
var expected = { date: Number(syncdate), rowId: Number(syncid) };
setLocal("%payload", JSON.stringify({ checkpoint: expected, rows: events }));
setLocal("%inboxcount", String(events.length));
setLocal("%inboxrowcount", String(rows.length));

var code = typeof http_response_code === "undefined" ? "" : String(http_response_code);
var response;
try {
  response = JSON.parse(String(http_data));
} catch (_error) {
  response = null;
}
var acknowledged = response && response.checkpoint;
var validResponse = code === "202" && response && Array.isArray(response.results) &&
  response.results.length === Number(inboxcount) && acknowledged &&
  isFinite(Number(acknowledged.date)) && Number(acknowledged.date) >= 0 &&
  Math.floor(Number(acknowledged.date)) === Number(acknowledged.date) &&
  isFinite(Number(acknowledged.rowId)) && Number(acknowledged.rowId) >= 0 &&
  Math.floor(Number(acknowledged.rowId)) === Number(acknowledged.rowId);
if (!validResponse) {
  var detail = typeof errmsg !== "undefined" && errmsg ? errmsg :
    (typeof http_data !== "undefined" && http_data ? http_data : "No response");
  flashLong("Actual SMS inbox sync failed; server checkpoint controls retry: " + detail);
  exit();
}
setLocal("%syncdate", String(acknowledged.date));
setLocal("%syncid", String(acknowledged.rowId));
var completedBatches = Number(batchnumber) + 1;
setLocal("%batchnumber", String(completedBatches));
if (Number(inboxrowcount) === 25 && completedBatches < 10) {
  inboxrows = [];
  setLocal("%drainmore", "1");
}

setLocal("%rewindpayload", JSON.stringify({ date: Date.now() - 7 * 24 * 60 * 60 * 1000 }));
setLocal("%http_response_code", "");
setLocal("%http_data", "");
setLocal("%errmsg", "");

var code = typeof http_response_code === "undefined" ? "" : String(http_response_code);
var response;
try {
  response = JSON.parse(String(http_data));
} catch (_error) {
  response = null;
}
if (code === "200" && response && response.checkpoint) {
  if (response.changed === false) {
    flashLong("Actual SMS inbox was already at least seven days back; the next sync will reconcile it");
  } else {
    flashLong("Actual SMS inbox checkpoint rewound seven days; the next sync will reconcile it");
  }
} else {
  var detail = typeof errmsg !== "undefined" && errmsg ? errmsg :
    (typeof http_data !== "undefined" && http_data ? http_data : "No response");
  flashLong("Actual SMS inbox rewind failed: " + detail);
}
